import sys
import os

# 添加项目根目录到路径
project_root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.append(project_root)

try:
    from scripts.data_source_manager import create_default_manager, DataSourceManager
except ImportError:
    # 如果scripts模块不存在，创建简化版本
    print("警告: 无法导入scripts模块，使用简化数据源")

    class SimpleDataSourceManager:
        def __init__(self):
            self.current_source = None

        def get_market_data(self, max_retries=2):
            import pandas as pd
            import numpy as np

            # 生成模拟数据
            np.random.seed(42)
            n_stocks = 100

            data = {
                '代码': [f'{i:06d}' for i in range(1, n_stocks + 1)],
                '名称': [f'股票{i}' for i in range(1, n_stocks + 1)],
                '涨跌幅': np.random.uniform(-10, 10, n_stocks).round(2),
                '换手率': np.random.uniform(0, 30, n_stocks).round(2),
                '成交额': np.random.uniform(100, 10000, n_stocks).round(2),
                '总市值': np.random.uniform(50, 5000, n_stocks).round(1),
            }

            self.current_source = type('MockSource', (), {'name': 'mock'})()
            return pd.DataFrame(data)

        def get_status_report(self):
            return "数据源状态: 使用模拟数据\n当前数据源: mock\n建议: 安装完整的数据源管理器"

    def create_default_manager():
        return SimpleDataSourceManager()

    DataSourceManager = SimpleDataSourceManager
